program='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    boxes = []

    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = all(grid[r][c] == color
                        for r in range(r0, r1 + 1)
                        for c in range(c0, c1 + 1)
                        if r in (r0, r1) or c in (c0, c1))
        interior_ok = all(grid[r][c] in (0, color)
                          for r in range(r0 + 1, r1)
                          for c in range(c0 + 1, c1))
        if perimeter and interior_ok:
            pattern = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                       for r in range(r0 + 1, r1)]
            boxes.append((color, r0, r1, c0, c1, pattern))

    sources = [b for b in boxes if any(any(row) for row in b[5])]
    if not sources:
        return out
    src = sources[0]
    sh, sw = src[1] - src[2] + 1, src[4] - src[3] + 1
    pattern = src[5]

    for color, r0, r1, c0, c1, _ in boxes:
        if color == src[0]:
            continue
        if r1 - r0 + 1 == sh and c1 - c0 + 1 == sw:
            for dr, row in enumerate(pattern, 1):
                for dc, filled in enumerate(row, 1):
                    out[r0 + dr][c0 + dc] = color if filled else 0
        else:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = 0
    return out
'''
p.parent.mkdir(parents=True,exist_ok=True)
